import { describe, expect, it } from 'vitest'
import { evaluateWorkload, parseGcodeText } from './analyzer'
import { DEFAULT_PRINTER_SETTINGS } from './domain/profile'
import {
  compareWithSlicer,
  parseDurationText,
  roleTargetSpeed,
  settingsFromSlicerMetadata,
  slicerMinimumLayerTime,
  slicerSlowDownMinSpeed,
} from './slicer-metadata'

const orcaGcode = [
  '; HEADER_BLOCK_START',
  '; generated by OrcaSlicer 2.3.1 on 2026-10-21 at 15:00:00',
  '; model printing time: 1h 29m 34s; total estimated time: 1h 33m 12s',
  '; HEADER_BLOCK_END',
  'G90',
  'M83',
  'SET_VELOCITY_LIMIT ACCEL=1500 ACCEL_TO_DECEL=750',
  ';LAYER_CHANGE',
  'G1 X100 E5 F3000',
  'M204 S5000',
  'G1 X0 F12000',
  '; estimated printing time (normal mode) = 1h 33m 12s',
  '; CONFIG_BLOCK_START',
  '; default_acceleration = 1500',
  '; filament_diameter = 1.75',
  '; filament_max_volumetric_speed = 10',
  '; machine_max_speed_x = 500,200',
  '; slow_down_layer_time = 12',
  '; sparse_infill_acceleration = 100%',
  '; CONFIG_BLOCK_END',
].join('\n')

describe('parseDurationText', () => {
  it('parses slicer duration formats', () => {
    expect(parseDurationText('1h 33m 12s')).toBe(5592)
    expect(parseDurationText('1d 2h 3m 4s')).toBe(93784)
    expect(parseDurationText('45s')).toBe(45)
    expect(parseDurationText('n/a')).toBeNull()
  })
})

describe('slicer metadata', () => {
  it('reads Orca estimate, slicer name and config block', () => {
    const { slicer } = parseGcodeText(orcaGcode)

    expect(slicer.slicer).toBe('OrcaSlicer 2.3.1')
    expect(slicer.estimatedSeconds).toBe(5592)
    expect(slicer.modelSeconds).toBe(5374)
    expect(slicer.estimateSource).toBe('total estimated time')
    expect(slicer.config.filament_max_volumetric_speed).toBe('10')
  })

  it('reads PrusaSlicer and Cura estimates', () => {
    expect(
      parseGcodeText(
        '; estimated printing time (normal mode) = 2h 5m 0s\n; estimated printing time (silent mode) = 3h',
      ).slicer.estimatedSeconds,
    ).toBe(7500)
    expect(parseGcodeText(';FLAVOR:Marlin\n;TIME:5612').slicer.estimatedSeconds).toBe(5612)
  })

  it('collects emitted accelerations from M204 and SET_VELOCITY_LIMIT', () => {
    expect(parseGcodeText(orcaGcode).emittedAccelerations).toEqual([1500, 5000])
  })

  it('fills audit limits from the config block and disables layer pauses', () => {
    const { slicer } = parseGcodeText(orcaGcode)
    const { settings, applied } = settingsFromSlicerMetadata(slicer, {
      ...DEFAULT_PRINTER_SETTINGS,
      minimumLayerTime: 5,
    })

    expect(settings).toEqual({
      maxVolumetricFlow: 10,
      maxPrintSpeed: 500,
      acceleration: 1500,
      minimumLayerTime: 0,
      filamentDiameter: 1.75,
    })
    expect(applied.map((item) => item.key)).toContain('default_acceleration')
  })

  it('reads slicer layer cooling independently of the audit profile', () => {
    const { slicer } = parseGcodeText(orcaGcode)

    expect(slicerMinimumLayerTime(slicer.config)).toBe(12)
    expect(slicerSlowDownMinSpeed(slicer.config)).toBeNull()
    expect(roleTargetSpeed('Outer wall', { outer_wall_speed: '100' })).toBe(100)
    expect(roleTargetSpeed('Sparse infill', { sparse_infill_speed: '180' })).toBe(180)
    expect(slicerMinimumLayerTime({ slow_down_layer_time: '0' })).toBe(0)
  })

  it('keeps manual settings for files without slicer metadata', () => {
    const { slicer } = parseGcodeText('G90\nG1 X10 F600')
    const { settings, applied } = settingsFromSlicerMetadata(
      slicer,
      DEFAULT_PRINTER_SETTINGS,
    )

    expect(settings).toEqual(DEFAULT_PRINTER_SETTINGS)
    expect(applied).toEqual([])
  })
})

describe('compareWithSlicer', () => {
  it('classifies agreement against the slicer estimate', () => {
    const { slicer } = parseGcodeText(orcaGcode)

    expect(compareWithSlicer(5592, slicer)?.agreement).toBe('match')
    expect(compareWithSlicer(5592 * 1.1, slicer)?.agreement).toBe('close')
    expect(compareWithSlicer(5592 * 0.7, slicer)?.deltaPercent).toBeCloseTo(-30, 5)
    expect(compareWithSlicer(5592 * 0.7, slicer)?.agreement).toBe('off')
  })

  it('returns null without a slicer estimate', () => {
    const workload = parseGcodeText('G90\nG1 X10 F600')
    const result = evaluateWorkload(workload, DEFAULT_PRINTER_SETTINGS)

    expect(compareWithSlicer(result.estimatedSeconds, workload.slicer)).toBeNull()
  })
})

describe('object names', () => {
  it('collects model names from Klipper, Orca/Prusa and Cura markers', () => {
    const { slicer } = parseGcodeText(
      [
        'EXCLUDE_OBJECT_DEFINE NAME=Atlast_PS5_Controller_Stand.stl_id_0_copy_0 CENTER=1,2',
        '; printing object Atlast PS5 Controller Stand.stl id:0 copy 0',
        '; stop printing object Atlast PS5 Controller Stand.stl id:0 copy 0',
        '; printing object Benchy.3mf id:1 copy 0',
        ';MESH:NONMESH',
        ';MESH:Cube.stl',
        'G1 X10 F600',
      ].join('\n'),
    )

    expect(slicer.objects).toEqual(['Atlast PS5 Controller Stand', 'Benchy', 'Cube'])
  })
})
